function mergeCityCourts(items){for(const item of items){const existing=courts.find(c=>c.city==='Phoenix'&&cityNameKey(c.name)===cityNameKey(item.name));if(existing){const id=existing.id;Object.assign(existing,item,{id});}else if(!courts.some(c=>c.id===item.id))courts.push(item);}}
mergeCityCourts(phoenixDirectory.parks);
try{const saved=JSON.parse(localStorage.getItem('bucketlist-park-directory')||'[]');for(const c of saved){if(!c||!/^osm-(node|way|relation)-[0-9]+$/.test(c.id)||typeof c.name!=='string'||!Number.isFinite(c.lat)||!Number.isFinite(c.lng)||courts.some(x=>x.id===c.id))continue;const same=courts.find(x=>cityNameKey(x.name)===cityNameKey(c.name));if(same)courts.push({...same,id:c.id,hiddenDuplicateOf:same.id});else courts.push(c);}}catch{}

