const defaults = () => ({custom:[],joined:[],groups:[],messages:{},teams:{},teamNames:{},stats:[],profile:{name:'You',bio:'',level:'All levels',shareProfile:false,shareStats:false}});
function readState(storageKey='bucketlist-demo-v2'){
 const base=defaults();
 try {
  const raw=JSON.parse(localStorage.getItem(storageKey))||(storageKey==='bucketlist-demo-v2'?JSON.parse(localStorage.getItem('bucketlist-demo-v1')):null);
  if(!raw)return base;
  base.custom=Array.isArray(raw.custom)?raw.custom.filter(g=>g&&typeof g.id==='string'&&/^local-[\w-]+$/.test(g.id)&&courts.some(c=>c.id===g.courtId)&&typeof g.title==='string'&&Number.isFinite(Date.parse(g.startsAt))&&Number.isInteger(g.capacity)&&g.capacity>=2&&g.capacity<=20).map(g=>({id:g.id,courtId:g.courtId,title:g.title.slice(0,80),startsAt:g.startsAt,...(g.endsAt&&validSchedule(g.startsAt,g.endsAt,g.durationMinutes,new Date(0))?{endsAt:g.endsAt,durationMinutes:g.durationMinutes,timeZone:String(g.timeZone||'')}:{}),capacity:g.capacity,level:String(g.level||'All levels'),note:String(g.note||''),players:[]})):[];
  const known=[...sampleGames,...base.custom];
  base.joined=Array.isArray(raw.joined)?[...new Set(raw.joined.filter(id=>known.some(g=>g.id===id)))]:[];
  base.groups=Array.isArray(raw.groups)?[...new Set(raw.groups.filter(id=>courts.some(c=>c.id===id)))]:[];
  for(const [key,value] of Object.entries(raw.messages||{})){if(Array.isArray(value))base.messages[key]=value.filter(m=>typeof m==='string').map(m=>m.slice(0,500)).slice(-100);}
  for(const [key,value] of Object.entries(raw.teams||{})){if(base.joined.includes(key)&&['A','B'].includes(value))base.teams[key]=value;}
  for(const [id,names] of Object.entries(raw.teamNames||{})){if(known.some(g=>g.id===id)&&names&&typeof names==='object')base.teamNames[id]={A:typeof names.A==='string'?names.A.slice(0,28):'Team A',B:typeof names.B==='string'?names.B.slice(0,28):'Team B'};}
  base.stats=Array.isArray(raw.stats)?raw.stats.filter(s=>s&&typeof s.id==='string'&&validStatEntry(s,today())).map(s=>({...s,note:String(s.note||'').slice(0,120)})):[];
  if(raw.profile&&typeof raw.profile==='object')base.profile={name:String(raw.profile.name||'You').slice(0,40),bio:String(raw.profile.bio||'').slice(0,250),level:String(raw.profile.level||'All levels'),shareProfile:raw.profile.shareProfile===true,shareStats:raw.profile.shareStats===true};
 } catch {}
 return base;
}
let themePreference='system';
try {const saved=localStorage.getItem('bucketlist-theme');if(['light','dark','system'].includes(saved))themePreference=saved;}catch{}
function applyTheme(preference){
 themePreference=preference;
 const dark=preference==='dark'||(preference==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);
 document.documentElement.dataset.theme=dark?'dark':'light';
 $('#theme-toggle').textContent=dark?'☼ Light mode':'◐ Dark mode';$('#theme-toggle').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');
 document.querySelector('meta[name="theme-color"]').content=dark?'#101111':'#f4f3ee';
 try{localStorage.setItem('bucketlist-theme',preference);}catch{}
}
let signedIn=false,pendingAction=null;
try{signedIn=sessionStorage.getItem('bucketlist-demo-session')==='active';}catch{}
function requireSession(action){if(signedIn)return true;openLogin(action);return false;}
function openLogin(action){pendingAction=action;showDialog('YOUR PLAYER PROFILE',`<div class="login-brand">${pinLogo()}<h2>Bucketlist</h2><p>Let’s Play.</p></div><p class="muted">Give your game a home. Create a player profile to keep your team, conversations, and progress together.</p><div class="profile-benefits"><div><strong>Find your crew</strong><span>Join teams and keep your game plans together.</span></div><div><strong>Keep the conversation going</strong><span>Coordinate in game chats and court communities.</span></div><div><strong>See your progress</strong><span>Log sessions, follow your stats, and choose what you share.</span></div></div><form id="login-form" class="stack"><label>Your display name<input name="displayName" maxlength="40" value="${state.profile.name==='You'?'':esc(state.profile.name)}" placeholder="What should the crew call you?" required autocomplete="nickname"></label><p class="form-error" id="login-error" role="alert"></p><button class="primary">CREATE / OPEN DEMO PROFILE</button></form><button class="secondary full" id="preview-profile-benefits">Explore a populated player demo</button><button class="text-button full" id="guest-continue">Keep browsing as a guest</button><p class="note">Demo profile only: information is saved in this browser, not a secure online account. No password is collected. Profile details and stats are private by default.</p>`);$('#preview-profile-benefits').onclick=()=>{$('#detail-dialog').close();pendingAction=null;enterShowcase();};$('#guest-continue').onclick=()=>{pendingAction=null;$('#detail-dialog').close();};$('#login-form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('displayName').trim();if(!name){$('#login-error').textContent='Enter a display name.';return;}state.profile.name=name;signedIn=true;try{sessionStorage.setItem('bucketlist-demo-session','active');}catch{}save();const next=pendingAction;pendingAction=null;$('#detail-dialog').close();render();if(next)next();};}
let showcaseMode=false;try{showcaseMode=sessionStorage.getItem('bucketlist-showcase')==='active';}catch{}
let personalState=readState();let state=showcaseMode?readState('bucketlist-showcase-state'):personalState;if(showcaseMode){if(!state.stats.length)state=createShowcase();state.showcase=true;state.showcaseSince=createShowcase().showcaseSince;signedIn=true;}let tab='discover',query='Phoenix',selectedCourt='pierce',coordinates=null,currentDialog=null,whenFilter='upcoming',styleFilter='Any style',discoveryMode='parks',directoryScope=null;
const games=()=>[...sampleGames,...state.custom];
const courtById=id=>courts.find(c=>c.id===id);
const gameById=id=>games().find(g=>g.id===id);
const teamName=(id,team)=>state.teamNames[id]?.[team]||'Team '+team;
function save(){try{localStorage.setItem(showcaseMode?'bucketlist-showcase-state':'bucketlist-demo-v2',JSON.stringify(state));}catch{toast('Storage is unavailable. Changes will last only in this tab.');}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function distance(c){if(!coordinates)return null;const rad=n=>n*Math.PI/180;const a=Math.sin(rad(c.lat-coordinates.lat)/2)**2+Math.cos(rad(coordinates.lat))*Math.cos(rad(c.lat))*Math.sin(rad(c.lng-coordinates.lng)/2)**2;return 3959*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
function matchedCourts(){const found=courts.filter(c=>!c.hiddenDuplicateOf&&(coordinates?distance(c)<=30:directoryScope?c.city===directoryScope:[c.name,c.city,c.address].some(v=>v.toLowerCase().includes(query.toLowerCase()))));return coordinates?found.sort((a,b)=>distance(a)-distance(b)):found;}
function upcoming(courtId){return games().filter(g=>g.courtId===courtId&&new Date(g.startsAt)>new Date()).sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt));}
function roster(g){const players=g.players.map((id,index)=>({...people.find(p=>p.id===id),team:index%2?'B':'A'}));if(state.joined.includes(g.id))players.push({id:'you',name:state.profile.name,team:state.teams[g.id]||null});return players;}
function gameCard(g){const c=courtById(g.courtId),count=roster(g).length;return `<article class="game-card"><p class="eyebrow">${esc(gameTime(g))}</p><h3>${esc(g.title)}</h3><p class="location">${esc(c.name)} · ${esc(c.city)}</p><div class="chips"><span class="chip">${esc(g.level)}</span><span class="chip ${count===g.capacity?'':'green'}">${count}/${g.capacity} players</span>${signedIn&&state.teams[g.id]?`<span class="chip orange">Your team: ${esc(teamName(g.id,state.teams[g.id]))}</span>`:''}</div><button class="primary full" data-game="${g.id}">${signedIn&&state.joined.includes(g.id)?'Open game & team':'View scheduled game'} →</button></article>`;}
let leafletMap=null,markerLayer=null,selectedMarkerLayer=null,mapPopup=null,refreshClock=null;
const markerNodes=new Map();
const visibleCourts=()=>discoveryMode==='parks'?matchedCourts():matchedCourts().filter(c=>eligibleGames(c.id).length);
const eligibleGames=id=>availableGames(games(),id,g=>roster(g).length,new Date(),whenFilter,styleFilter);
function initMap(){
 if(leafletMap)return;
 leafletMap=L.map('court-map',{zoomControl:false,scrollWheelZoom:true,fadeAnimation:false}).setView([33.475,-112.02],12);
 L.control.zoom({position:'bottomright'}).addTo(leafletMap);
 const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a> contributors'}).addTo(leafletMap);
 let loaded=0;tiles.on('tileload',()=>{loaded++;$('#map-status').textContent='Pins = basketball parks · game availability shown separately';});
 tiles.on('tileerror',()=>{if(!loaded)$('#map-status').textContent='Street tiles unavailable · pins use sample court coordinates. Open Google Maps for directions.';});
 markerLayer=L.markerClusterGroup({showCoverageOnHover:false,maxClusterRadius:44,disableClusteringAtZoom:15,animate:false,iconCreateFunction:cluster=>L.divIcon({className:'court-cluster',html:'<span aria-label="'+cluster.getChildCount()+' basketball locations; activate to zoom">'+cluster.getChildCount()+'</span>',iconSize:[44,44]})}).addTo(leafletMap);selectedMarkerLayer=L.layerGroup().addTo(leafletMap);
 leafletMap.on('popupclose',()=>{for(const marker of markerNodes.values())marker.getElement()?.setAttribute('aria-expanded','false');});
 leafletMap.on('movestart',()=>{$('#refit-map').hidden=false;});
 refreshClock=setInterval(()=>{if(tab==='discover'&&!$('#detail-dialog').open){const previous=selectedCourt,wasOpen=mapPopup?.isOpen();renderDiscover(false);if(wasOpen&&selectedCourt===previous&&(discoveryMode==='parks'||eligibleGames(previous).length))courtPopup();}},60000);
}
function fitResults(){const available=visibleCourts();if(available.length)leafletMap.fitBounds(L.latLngBounds(available.map(c=>[c.lat,c.lng])),{padding:[65,85],maxZoom:15,animate:false});$('#refit-map').hidden=true;}
function renderMap(c,fit=false){
 initMap();markerLayer.clearLayers();selectedMarkerLayer.clearLayers();markerNodes.clear();leafletMap.closePopup();
 const candidates=visibleCourts();
 for(const court of candidates){
  const marker=L.marker([court.lat,court.lng],{title:court.name+' · basketball court listing',alt:court.name,keyboard:true,zIndexOffset:court.id===selectedCourt?1000:0,icon:L.divIcon({className:'court-pin',html:pinLogo(),iconSize:[44,64],iconAnchor:[22,64],popupAnchor:[0,-64]})});
  markerNodes.set(court.id,marker);
  marker.on('add',()=>{const el=marker.getElement();if(!el)return;el.id=court.id===selectedCourt?'court-marker':'court-marker-'+court.id;el.dataset.courtId=court.id;el.setAttribute('role','button');el.setAttribute('aria-label','Select '+court.name);el.setAttribute('aria-expanded','false');el.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();e.stopPropagation();marker.fire('click');}});});
  marker.on('click',()=>{selectedCourt=court.id;courtPopup();});
  marker.addTo(court.id===selectedCourt?selectedMarkerLayer:markerLayer);

 }
 $('#map-label').textContent=c?c.name+' · '+c.city:'No matching available court';$('#map-external').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(c?.address||query||'basketball courts');
 $('#court-map').dataset.selectedCourt=c?.id||'';$('#court-map').dataset.resultCount=String(candidates.length);
 if(fit)fitResults();
 requestAnimationFrame(()=>leafletMap.invalidateSize({pan:false}));
 if(!candidates.length)$('#map-status').textContent=discoveryMode==='parks'?'No basketball parks found in this directory area. Try live directory search.':'No matching games with open spots. Switch to All basketball parks to choose a venue.';
}
function renderDiscover(fit=true){
 document.body.classList.toggle('map-mode',tab==='discover');
 const found=matchedCourts(),available=visibleCourts();
 if(!available.some(c=>c.id===selectedCourt))selectedCourt=available[0]?.id||null;
 renderMap(courtById(selectedCourt),fit);$('#area-title').textContent=coordinates?'Courts near you':query?`Courts around ${query}`:'Explore courts';$('#court-count').textContent=available.length+(discoveryMode==='parks'?' parks':' with spots');
 $('#court-list').innerHTML=found.length?found.map(c=>{const open=eligibleGames(c.id).length;return `<article class="court-card ${c.id===selectedCourt?'selected':''}"><h3>${esc(c.name)}</h3><p class="location">${esc(c.address)}${coordinates?' · '+distance(c).toFixed(1)+' mi':''}</p><div class="chips"><span class="chip">${open?open+' matching games with open spots':'No matching scheduled spots'}</span><span class="chip">${c.source==='City of Phoenix'?'City of Phoenix · basketball listed':c.source?'OSM basketball listing':'Demo venue · unverified'}</span></div><button class="${open?'primary':'secondary'} full" data-map="${c.id}">${open?'Choose park · games available':'Choose park · start a game'}</button></article>`;}).join(''):'<div class="empty"><h3>No basketball parks found in this directory.</h3><p>Try Phoenix, Scottsdale, or Austin.</p><button class="secondary" data-reset>Explore Phoenix</button></div>';
}
function pinLogo(){return `<svg viewBox="0 0 100 150" aria-hidden="true"><path d="M50 6C24 6 8 25 8 48c0 21 25 73 34 90 4 8 12 8 16 0 9-17 34-69 34-90C92 25 76 6 50 6Z" fill="#f45422" stroke="#242321" stroke-width="7"/><circle cx="50" cy="47" r="25" fill="none" stroke="#242321" stroke-width="6"/><path d="M25 47h50M50 22v50M32 28c13 11 13 27 0 39M68 28C55 39 55 55 68 67" fill="none" stroke="#242321" stroke-width="5"/></svg>`;}
function courtPopup(){
 const c=courtById(selectedCourt);if(!c)return;
 const runs=eligibleGames(c.id),spots=runs.reduce((n,g)=>n+g.capacity-roster(g).length,0);
 const content=document.createElement('div');content.id='court-popup';content.className='court-popup';content.setAttribute('role','region');content.setAttribute('aria-label',c.name+' available games');
 content.innerHTML=`<button class="popup-close" id="close-popup" aria-label="Close court popup">×</button><h2><button class="popup-title" data-court="${c.id}">${esc(c.name)} <span>›</span></button></h2><p>${esc(c.city)}</p><div>${runs.length} ${runs.length===1?'Game':'Games'} · ${runs.length*2} Teams</div><p class="request-dot">${spots?spots+' open roster spots · sample':'No scheduled game · start one here'}</p><p class="availability-note">Not live court occupancy</p><button class="primary full" data-create="${c.id}">START A GAME</button>`;
 mapPopup=L.popup({closeButton:false,className:'bucketlist-map-popup',maxWidth:240,autoPanPadding:[25,85]}).setLatLng([c.lat,c.lng]).setContent(content).openOn(leafletMap);
 for(const [id,marker] of markerNodes)marker.getElement()?.setAttribute('aria-expanded',String(id===c.id));
 $('#close-popup').onclick=()=>{leafletMap.closePopup();markerNodes.get(c.id)?.getElement()?.focus();};
}
function toggleSearch(open){if(open&&tab!=='discover'){tab='discover';render();}$('#map-search').hidden=!open;$('#search-toggle').setAttribute('aria-expanded',String(open));if(open){leafletMap?.closePopup();$('#location').focus();}}
function renderGames(){const mine=games().filter(g=>state.joined.includes(g.id)),future=mine.filter(g=>new Date(g.startsAt)>new Date()),past=mine.filter(g=>new Date(g.startsAt)<=new Date()).sort((a,b)=>new Date(b.startsAt)-new Date(a.startsAt));$('#my-games-list').innerHTML=mine.length?'<p class="section-label">Upcoming games · '+future.length+'</p>'+future.map(gameCard).join('')+'<p class="section-label">Played sessions · '+past.length+'</p>'+past.map(g=>`<article class="game-card"><p class="eyebrow">${esc(gameTime(g))} · COMPLETED DEMO</p><h3>${esc(g.title)}</h3><p class="muted">${esc(courtById(g.courtId)?.name)} · ${esc(teamName(g.id,state.teams[g.id]||'A'))}</p><button class="secondary full" data-session-stats="${g.id}">View session stats</button></article>`).join(''):'<div class="empty"><h3>Your crew is out there.</h3><p>Choose any basketball park to start the next game.</p><button class="secondary" data-go="discover">Find a court</button></div>';}
function renderChats(){
 const courtChats=courts.filter(c=>state.groups.includes(c.id));const gameChats=games().filter(g=>state.joined.includes(g.id)&&new Date(g.startsAt)>new Date());
 $('#chat-list').innerHTML=[...gameChats.map(g=>`<article class="chat-card"><button data-game="${g.id}" data-game-tab="chat"><h3>${esc(g.title)}<span>→</span></h3><p class="location">Game group · ${esc(courtById(g.courtId).name)}</p><p class="muted">${esc((state.messages[g.id]||[]).at(-1)||'Coordinate with the team before you head out.')}</p></button></article>`),...courtChats.map(c=>`<article class="chat-card"><button data-court="${c.id}" data-court-tab="chat"><h3>${esc(c.name)}<span>→</span></h3><p class="location">Court community</p><p class="muted">${esc((state.messages['court:'+c.id]||[]).at(-1)||'A home for the crew, beyond a single game.')}</p></button></article>`)].join('')||'<div class="empty"><h3>Meet your next crew.</h3><p>Join a game or a court community to open its chat.</p><button class="secondary" data-go="discover">Explore courts</button></div>';
}
function statTiles(stats){return `<div class="stat-grid"><div class="stat-tile"><strong>${stats.points}</strong><span>POINTS / SESSION</span></div><div class="stat-tile"><strong>${stats.rebounds}</strong><span>REBOUNDS / SESSION</span></div><div class="stat-tile"><strong>${stats.assists}</strong><span>ASSISTS / SESSION</span></div></div><p class="note">${stats.count} self-reported ${stats.count===1?'session':'sessions'}. Not official or independently verified.</p>`;}
function renderStats(){
 $('#stats-summary').innerHTML=`${statTiles(statSummary(state.stats))}${showcaseMode?showcaseProgress():''}<div class="privacy-box">${state.profile.shareStats?'Stats sharing is on in your public preview.':'Your stats are private.'} <button class="text-button" data-go="profile">Manage visibility →</button></div>`;
 $('#stat-history').innerHTML='<p class="section-label">Session history</p>'+(state.stats.length?[...state.stats].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<article class="stat-entry"><div><h3>${esc(s.date)}</h3><button class="text-button" data-delete-stat="${esc(s.id)}" aria-label="Delete session ${esc(s.date)}">Delete</button></div><p class="muted">${s.points} PTS · ${s.rebounds} REB · ${s.assists} AST${s.note?'<br>'+esc(s.note):''}</p></article>`).join(''):'<div class="empty"><h3>Your next session starts the story.</h3><p>Add your first stats after you play. Only you can edit them in this local demo.</p></div>');
}
function renderProfile(){const p=state.profile;$('#profile-content').innerHTML=`<div class="page-heading"><p class="eyebrow">YOUR GAME. YOUR CALL.</p><h1>Player profile.</h1></div><div class="profile-hero"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.level)}</p>${showcaseMode?'<p class="note">Fictional member since '+esc(state.showcaseSince)+'</p>':''}</div></div><div class="privacy-box">Choose what other players can view. Your display name remains visible on rosters. Profile details and stats have separate controls, both off by default.</div><form id="profile-form" class="stack"><label>Appearance<select name="theme">${[['system','Use device setting'],['light','Light'],['dark','Dark']].map(([v,label])=>`<option value="${v}" ${themePreference===v?'selected':''}>${label}</option>`).join('')}</select></label><label>Display name<input name="name" maxlength="40" value="${esc(p.name)}" required></label><label>About your game<textarea name="bio" maxlength="250" placeholder="How you like to play…">${esc(p.bio)}</textarea></label><label>Play style<select name="level">${levels(p.level)}</select></label><label class="check-row"><input name="shareProfile" type="checkbox" ${p.shareProfile?'checked':''}><span>Show my profile details<small>Allow other players to view your bio and play style.</small></span></label><label class="check-row"><input name="shareStats" type="checkbox" ${p.shareStats?'checked':''}><span>Show my stats<small>Allow other players to view your self-reported averages.</small></span></label><p class="form-error" id="profile-error" role="alert"></p><button class="primary">Save profile & privacy</button></form><button class="secondary full" id="preview-profile">Preview what others can see</button><button class="secondary full" id="sign-out">Sign out of local demo</button><p class="note">Local demo: these settings change the public preview on this device. A production app must enforce access permissions on its server.</p>`;
 $('#profile-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),name=data.get('name').trim();if(!name){$('#profile-error').textContent='Enter a display name.';return;}applyTheme(data.get('theme'));state.profile={name,bio:data.get('bio').trim(),level:data.get('level'),shareProfile:data.has('shareProfile'),shareStats:data.has('shareStats')};save();render();toast('Profile and visibility saved.');};$('#preview-profile').onclick=()=>openPlayer('you',true);$('#sign-out').onclick=()=>{signedIn=false;try{sessionStorage.removeItem('bucketlist-demo-session');}catch{}go('discover');toast('Signed out. Device-local demo data is retained.');};
}
function render(){$('#showcase-badge').hidden=!showcaseMode;$('#exit-showcase').hidden=!showcaseMode;$('#load-showcase').textContent=showcaseMode?'Restart populated showcase':'Explore 90-day player demo';document.body.classList.toggle('map-mode',tab==='discover');document.querySelectorAll('.screen').forEach(s=>s.hidden=s.id!==tab+'-screen');document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(signedIn)$('#open-profile').textContent=state.profile.name.slice(0,2).toUpperCase();else $('#open-profile').innerHTML='<svg class="user-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3Z"/></svg>';$('#open-profile').setAttribute('aria-label',signedIn?'Your profile and privacy':'Sign in');if(tab==='discover')renderDiscover();if(tab==='games')renderGames();if(tab==='chats')renderChats();if(tab==='stats')renderStats();if(tab==='profile')renderProfile();}
function go(next){if(next!=='discover'&&!requireSession(()=>go(next)))return;$('#app-menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');toggleSearch(false);tab=next;render();window.scrollTo({top:0});if(next==='discover')requestAnimationFrame(()=>leafletMap?.invalidateSize());}
function showDialog(label,html){$('#detail-dialog').classList.remove('court-info-dialog');$('#dialog-label').textContent=label;$('#details').innerHTML=html;const heading=$('#details h2');if(heading){heading.id='detail-title';heading.tabIndex=-1;$('#detail-dialog').setAttribute('aria-labelledby','detail-title');}if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;if(heading)heading.focus({preventScroll:true});}
const levels=value=>['All levels','Beginner friendly','Intermediate','Competitive','Adaptive basketball'].map(l=>`<option ${l===value?'selected':''}>${l}</option>`).join('');
function openCourt(id,section='games'){
 const c=courtById(id);if(!c)return;currentDialog={type:'court',id,section};selectedCourt=id;if(tab==='discover')renderMap(c);const joined=signedIn&&state.groups.includes(id),runs=upcoming(id);const spots=runs.reduce((n,g)=>n+g.capacity-roster(g).length,0);
 showDialog('COURT DETAILS',`<div class="court-reference-heading"><div><h2>${esc(c.name)}</h2><p>${esc(c.address)}</p></div><span class="unrated">Not rated<small>No verified reviews</small></span></div>${c.source==='City of Phoenix'?`<p class="source-detail">City of Phoenix directory · ${c.courtIds.length?c.courtIds.length+' mapped basketball court'+(c.courtIds.length===1?'':'s'):'basketball listed'}<br>${esc(c.locationType)} · checked ${esc(c.checkedAt.slice(0,10))}<br>Restrooms: ${esc(c.amenities.restrooms)} · Drinking water: ${esc(c.amenities.drinkingWater)}<br><a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">View city source →</a></p>`:''}<p class="request-dot">${spots} open game spots · sample rosters</p><div class="court-preview" aria-label="Illustrated basketball court, not a venue photograph"><div class="court-lines"></div><span>COURT PREVIEW · ILLUSTRATION</span></div><div class="court-summary"><button data-court-section="games">◎ ${runs.length} Games <span>${runs[0]?Math.ceil(runs[0].capacity/2)+'v'+Math.floor(runs[0].capacity/2)+' games':'Start the next run'}</span></button><button data-court-section="teams">♙ ${runs.length*2} Teams <span class="request-dot">${spots} open spots</span></button><button data-court-section="chat">◌ Court community <span>Chat →</span></button></div><div id="court-section">${section==='games'?'<div class="court-expanded" hidden>'+runs.map(gameCard).join('')+'</div>':section==='teams'?runs.map(g=>`<section class="court-game-preview"><p class="eyebrow">${esc(gameTime(g))}</p><h3>${esc(g.title)}</h3><div class="team-grid">${['A','B'].map(team=>`<div><h3>${esc(teamName(g.id,team))}</h3><ul>${signedIn?roster(g).filter(p=>p.team===team).map(p=>`<li>${esc(p.name)}</li>`).join(''):'<li>'+roster(g).filter(p=>p.team===team).length+' players · profiles hidden</li>'}</ul></div>`).join('')}</div><button class="secondary full" data-game="${g.id}">View game & join a team</button></section>`).join(''):joined?chatMarkup('court:'+id,'Court community'):'<div class="empty"><h3>Join the court group.</h3><p>Keep the crew connected between games.</p><button class="primary" id="join-community">'+(signedIn?'Join court group':'Sign in to join court group')+'</button></div>'}</div><button class="primary full court-start" data-create="${id}">START A GAME</button><a class="text-button" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(c.address)}" target="_blank" rel="noopener noreferrer">Directions in Google Maps →</a><p class="note">Sample venue. Access, lighting, and accessibility are unverified. ${signedIn?'Local demo session.':'Browse freely. Sign in to join or organize a game.'}</p>`);
 $('#detail-dialog').classList.add('court-info-dialog');
 $('#details').querySelectorAll('[data-court-section]').forEach(b=>b.onclick=()=>{if(b.dataset.courtSection==='games'&&section==='games'){$('.court-expanded').hidden=!$('.court-expanded').hidden;}else openCourt(id,b.dataset.courtSection);});
 const join=$('#join-community');if(join)join.onclick=()=>{if(!requireSession(()=>openCourt(id,'chat')))return;if(!state.groups.includes(id))state.groups.push(id);save();openCourt(id,'chat');};bindChat('court:'+id,()=>openCourt(id,'chat'));
}
function playerRow(p){if(!signedIn)return `<div class="player-row"><span class="player-badge" aria-hidden="true">?</span><span class="muted">Player profile · members only</span></div>`;return `<div class="player-row"><span class="player-badge">${esc(p.name.slice(0,2).toUpperCase())}</span><button data-player="${p.id}">${esc(p.name)}${p.id==='you'?'<small>You</small>':`<small>${p.shareProfile?'View profile':'Profile private'}</small>`}</button></div>`;}
function openGame(id,section='teams'){
 const g=gameById(id);if(!g)return;currentDialog={type:'game',id,section};const c=courtById(g.courtId),joined=signedIn&&state.joined.includes(id),players=roster(g),full=players.length>=g.capacity;
 let content='';
 if(section==='teams')content=`<div class="section-heading"><h3>Build your team</h3><span class="pill">${players.length}/${g.capacity} players</span></div><p class="muted">Choose a side for this scheduled game. ${joined&&!state.teams[id]?'You’re on the roster. Pick your team below.':''}</p><div class="team-grid">${['A','B'].map(team=>{const members=players.filter(p=>p.team===team),selected=state.teams[id]===team,allowed=new Date(g.startsAt)>new Date()&&canJoinTeam(g,players,team,joined,state.teams[id]);return `<section class="team-box"><h3>${esc(teamName(id,team))}<span>${members.length}/${teamCapacity(g.capacity,team)}</span></h3><div class="roster">${members.map(playerRow).join('')||'<p class="muted">First spot is yours.</p>'}</div><button class="${selected?'secondary':'primary'} full" data-team="${team}" ${selected||!allowed?'disabled':''}>${selected?'Your team':allowed?'Join Team '+team:'Team full'}</button></section>`;}).join('')}</div>${players.some(p=>!p.team)?'<p class="section-label">Not on a team yet</p><div class="roster">'+players.filter(p=>!p.team).map(playerRow).join('')+'</div>':''}${joined&&state.teams[id]?`<form id="team-name-form" class="stack"><label>Name your team<input name="teamName" maxlength="28" value="${esc(teamName(id,state.teams[id]))}" required></label><button class="secondary">Save team name</button></form>`:''}<p class="note">Other players shown are fictional examples. Team limits are enforced on this device, not reserved on a shared server.</p>`;
 if(section==='chat')content=joined?chatMarkup(id,'Game group'):'<div class="empty"><h3>Join the run to enter the chat.</h3><p>Choose a team or join the roster first.</p></div>';
 if(section==='info')content=`<p class="section-label">Meeting details</p><p class="detail-subtitle">${esc(g.note)}</p><p class="section-label">Play style</p><p class="muted">${esc(g.level)}</p><button class="secondary full" data-court="${c.id}">View court & community →</button><a class="text-button" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(c.address)}" target="_blank" rel="noopener noreferrer">Get directions ↗</a><p class="note">Times are shown in your device’s timezone. Verify venue access and participants before heading out.</p>`;
 showDialog('SCHEDULED GAME',`<p class="eyebrow">${esc(gameTime(g))}</p><h2 class="detail-heading">${esc(g.title)}</h2><p class="detail-subtitle">${esc(c.name)} · ${esc(c.city)}</p><div class="chips"><span class="chip">${esc(g.level)}</span><span class="chip orange">${g.capacity-players.length} open spots</span><span class="chip">Local demo</span></div>${!signedIn?guestProfilePrompt():''}${joined?`<div class="info-banner">You’re on the roster.${state.teams[id]?' Team '+state.teams[id]+' is your side.':' Choose your team below.'}</div>`:`<button id="join-game" class="primary full" ${full||new Date(g.startsAt)<=new Date()?'disabled':''}>${new Date(g.startsAt)<=new Date()?'Game completed':full?'Game full':'Join game · choose a team next'}</button>`}<div class="game-tabs" role="tablist" aria-label="Game sections">${[['teams','Teams'],['chat','Game chat'],['info','Details']].map(([key,label])=>`<button role="tab" data-game-section="${key}" aria-selected="${section===key}">${label}</button>`).join('')}</div>${content}${joined?'<button id="leave-game" class="text-button">Leave this game</button>':''}`);
 $('#details').querySelectorAll('[data-game-section]').forEach(b=>b.onclick=()=>openGame(id,b.dataset.gameSection));
 const join=$('#join-game');if(join)join.onclick=()=>{if(!requireSession(()=>openGame(id)))return;if(new Date(g.startsAt)<=new Date()||roster(g).length>=g.capacity)return;state.joined.push(id);save();render();openGame(id,'teams');toast('Joined the local roster. Choose your team.');};
 $('#details').querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{const team=b.dataset.team;if(new Date(g.startsAt)<=new Date())return;if(!requireSession(()=>openGame(id)))return;if(!canJoinTeam(g,roster(g),team,state.joined.includes(id),state.teams[id]))return;if(!state.joined.includes(id))state.joined.push(id);state.teams[id]=team;save();render();openGame(id,'teams');toast('You’re on Team '+team+'.');});
 const leave=$('#leave-game');if(leave)leave.onclick=()=>{state.joined=state.joined.filter(x=>x!==id);delete state.teams[id];save();render();openGame(id);toast('You left the game and team.');};const nameForm=$('#team-name-form');if(nameForm)nameForm.onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('teamName').trim();if(!name){toast('Enter a team name.');return;}const team=state.teams[id];state.teamNames[id]={A:teamName(id,'A'),B:teamName(id,'B'),[team]:name};save();render();openGame(id,'teams');toast('Team name saved on this device.');};bindChat(id,()=>openGame(id,'chat'));
}
function chatMarkup(key,label){const seeded=showcaseMode?(key.startsWith('court:')?[{name:'Jordan M.',text:'Great run last weekend. Who’s up for another beginner-friendly game?'},{name:'Casey T.',text:'I’m in! Can we confirm the meeting spot before we head out?'}]:[{name:'Alex C.',text:'I’ll bring a ball. Light and dark shirts for teams?'},{name:'Jordan M.',text:'Yes! Meet at the entrance 15 minutes before the game.'}]):[];const messages=state.messages[key]||[];return `<p class="section-label">${label}</p><div class="messages" aria-label="${label} messages"><div class="message"><strong>BucketList · Demo notice</strong>Messages here stay in this browser. They are not sent to other players.</div>${seeded.map(m=>`<div class="message"><strong>${esc(m.name)} · Fictional player</strong>${esc(m.text)}</div>`).join('')}${messages.map(m=>`<div class="message own"><strong>${esc(state.profile.name)} · You</strong>${esc(m)}</div>`).join('')}</div><form class="chat-form" id="chat-form"><input aria-label="Message ${label.toLowerCase()}" placeholder="Coordinate the next run…" maxlength="500" required><button class="primary" type="submit">Send</button></form>`;}
function bindChat(key,reopen){const form=$('#chat-form');if(!form)return;form.onsubmit=e=>{e.preventDefault();if(!requireSession(reopen))return;const value=form.querySelector('input').value.trim();if(!value)return;state.messages[key]=[...(state.messages[key]||[]),value].slice(-100);save();render();reopen();$('.messages').scrollTop=$('.messages').scrollHeight;$('#chat-form input').focus();};}
function openPlayer(id,preview=false){if(!requireSession(()=>openPlayer(id,preview)))return;
 const original=id==='you'?{...state.profile,id:'you',stats:statSummary(state.stats)}:people.find(p=>p.id===id);if(!original)return;const p=visiblePlayer(original,id==='you'&&signedIn&&!preview);const back=currentDialog?.type==='game'?{...currentDialog}:null;
 showDialog(preview?'YOUR PUBLIC PREVIEW':'PLAYER PROFILE',`<div class="profile-hero"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><div><h2>${esc(p.name)}</h2><p class="muted">${id==='you'?'Your profile preview':'Fictional demo player'}</p></div></div>${p.profileVisible?`<p class="section-label">About the player</p><p class="detail-subtitle">${esc(p.bio||'No bio added.')}</p><span class="chip">${esc(p.level||'Not specified')}</span>`:'<div class="privacy-box">Profile details are private. This player has not chosen to share them.</div>'}${p.statsVisible?`<p class="section-label">Self-reported stats</p>${statTiles(p.stats||statSummary([]))}`:'<div class="privacy-box">Stats are private. This player has not chosen to share them.</div>'}${back?'<button class="secondary full" id="back-to-game">← Back to game</button>':''}<p class="note">Public previews honor each sharing setting independently. This is a local UI demonstration; production privacy requires server-side authorization.</p>`);
 if(back)$('#back-to-game').onclick=()=>openGame(back.id,back.section);
}
function createGame(courtId=selectedCourt){if(!requireSession(()=>createGame(courtId)))return;currentDialog={type:'create'};showDialog('SCHEDULE A RUN',`<div id="create-intro"><p class="eyebrow">YOU GOT NEXT.</p><h2 class="detail-heading">Set the time. Build the team.</h2><p class="muted">Create a scheduled game at a court. Local demo only.</p></div><form id="create-form" class="stack"><label>Game name<input name="title" maxlength="80" placeholder="Evening pickup runs" required></label><label>Court<select name="court">${courts.filter(c=>!c.hiddenDuplicateOf).map(c=>`<option value="${c.id}" ${c.id===courtId?'selected':''}>${esc(c.name)} · ${esc(c.city)}</option>`).join('')}</select></label><div class="schedule-field"><span>Date & time</span><button type="button" class="secondary full" id="choose-game-time">Choose date & time →</button><p id="chosen-time" class="note" aria-live="polite">No time chosen yet.</p></div><div class="row"><label>Player limit<input name="capacity" type="number" min="2" max="20" value="10" required></label><label>Play style<select name="level">${levels('All levels')}</select></label></div><label>Meeting details & access needs<textarea name="note" maxlength="500" placeholder="Where to meet, what to bring, or accommodations to discuss"></textarea></label><p class="form-error" id="create-error" role="alert"></p><button type="submit" class="primary">Create game & choose team</button></form><div id="schedule-picker" hidden></div>`);
 let schedule=null;const form=$('#create-form'),picker=$('#schedule-picker');$('#choose-game-time').onclick=()=>{form.hidden=true;$('#create-intro').hidden=true;picker.hidden=false;$('#detail-dialog').setAttribute('aria-labelledby','time-picker-title');mountTimePicker(picker,{value:schedule,onCancel:()=>{picker.hidden=true;form.hidden=false;$('#create-intro').hidden=false;$('#detail-dialog').setAttribute('aria-labelledby','detail-title');$('#choose-game-time').focus();},onConfirm:value=>{schedule=value;picker.hidden=true;form.hidden=false;$('#create-intro').hidden=false;$('#detail-dialog').setAttribute('aria-labelledby','detail-title');$('#chosen-time').textContent=gameTime({startsAt:value.startsAt,endsAt:value.endsAt})+' · '+value.duration+' min · '+value.timeZone;$('#choose-game-time').textContent='Change date & time →';$('#choose-game-time').focus();}});$('#detail-dialog').scrollTop=0;picker.querySelector('h2').tabIndex=-1;picker.querySelector('h2').focus();};
 $('#create-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),title=data.get('title').trim(),starts=new Date(schedule?.startsAt||NaN),capacity=Number(data.get('capacity'));if(!title||!schedule||!validSchedule(schedule.startsAt,schedule.endsAt,schedule.duration)||!Number.isFinite(starts.getTime())||starts<=new Date()||!Number.isInteger(capacity)||capacity<2||capacity>20){$('#create-error').textContent='Enter a name, choose a future date/time, and use 2–20 players.';return;}const g={id:'local-'+uid(),courtId:data.get('court'),title,startsAt:starts.toISOString(),endsAt:schedule.endsAt,durationMinutes:schedule.duration,timeZone:schedule.timeZone,capacity,level:data.get('level'),note:data.get('note').trim()||'Coordinate meeting details in game chat.',players:[]};state.custom.push(g);state.joined.push(g.id);save();tab='games';render();openGame(g.id);toast('Local game scheduled. Pick your team.');};
}
function logStats(){if(!requireSession(logStats))return;currentDialog={type:'stats'};showDialog('PERSONAL STATS',`<p class="eyebrow">PUT IN THE WORK</p><h2 class="detail-heading">Log your session.</h2><p class="muted">Your own numbers, after you play. Self-reported, not an official score.</p><form id="stats-form" class="stack"><label>Session date<input name="date" type="date" value="${today()}" max="${today()}" required></label><div class="row">${[['points','Points'],['rebounds','Rebounds'],['assists','Assists']].map(([key,label])=>`<label>${label}<input name="${key}" type="number" min="0" max="200" value="0" required></label>`).join('')}</div><label>Court or session note<input name="note" maxlength="120" placeholder="Evening run at Encanto"></label><p class="form-error" id="stats-error" role="alert"></p><button class="primary">Save session</button></form><p class="note">${state.profile.shareStats?'Stats sharing is currently on.':'Private by default. Change visibility in Profile.'}</p>`);
 $('#stats-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),entry={id:uid(),date:data.get('date'),points:Number(data.get('points')),rebounds:Number(data.get('rebounds')),assists:Number(data.get('assists')),note:data.get('note').trim()};if(!validStatEntry(entry,today())){$('#stats-error').textContent='Use a valid date up to today and whole-number stats from 0 to 200.';return;}state.stats.push(entry);save();tab='stats';render();$('#detail-dialog').close();toast('Session saved to your personal stats.');};
}
// Shared event routing works for cards inside screens and dialogs.
document.addEventListener('click',e=>{
 const button=e.target.closest('button');if(!button)return;
 if(button.dataset.tab)go(button.dataset.tab);
 if(button.dataset.go){$('#detail-dialog').close();go(button.dataset.go);}
 if(button.dataset.map){selectedCourt=button.dataset.map;renderDiscover();toggleSearch(false);courtPopup();}
 if(button.dataset.court)openCourt(button.dataset.court,button.dataset.courtTab||'games');
 if(button.dataset.game)openGame(button.dataset.game,button.dataset.gameTab||'teams');
 if(button.dataset.create)createGame(button.dataset.create);
 if(button.dataset.sessionStats)showSessionStats(button.dataset.sessionStats);
 if(button.hasAttribute('data-create-profile'))openLogin(()=>openGame(currentDialog?.id||'pierce'));
 if(button.dataset.player)openPlayer(button.dataset.player);
 if(button.hasAttribute('data-reset')){coordinates=null;query='Phoenix';directoryScope=null;discoveryMode='parks';$('#discovery-mode').value='parks';whenFilter='upcoming';styleFilter='Any style';$('#when-filter').value=whenFilter;$('#style-filter').value=styleFilter;$('#location').value=query;go('discover');}
 if(button.dataset.deleteStat){state.stats=state.stats.filter(s=>s.id!==button.dataset.deleteStat);save();renderStats();toast('Session deleted.');}
});
$('#search-form').onsubmit=e=>{e.preventDefault();query=$('#location').value.trim();coordinates=null;directoryScope=null;renderDiscover();if(query.toLowerCase()==='phoenix')showCityCoverage();else loadDirectory(query);$('#location-status').textContent='Sample court search. The map shows the selected venue; it does not indicate live players.';};
$('#locate').onclick=()=>{if(!navigator.geolocation){$('#location-status').textContent='Location unavailable. Search a city instead.';return;}$('#locate').disabled=true;$('#location-status').textContent='Getting your location…';navigator.geolocation.getCurrentPosition(pos=>{coordinates={lat:pos.coords.latitude,lng:pos.coords.longitude};$('#location').value='Near me';renderDiscover();$('#location-status').textContent='Sample courts within 30 miles. Your coordinates stay in memory for filtering. Street tiles load from OpenStreetMap; Google opens only for directions.';$('#locate').disabled=false;},()=>{$('#location-status').textContent='Couldn’t get your location. Search a city or court instead.';$('#locate').disabled=false;},{timeout:10000,maximumAge:60000});};
$('#start-game').onclick=()=>createGame();$('#schedule-from-games').onclick=()=>createGame();$('#log-stats').onclick=logStats;$('#open-profile').onclick=()=>signedIn?go('profile'):openLogin(()=>go('profile'));$('#close-dialog').onclick=()=>$('#detail-dialog').close();
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();

$('#theme-toggle').onclick=()=>{applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');if(tab==='profile')renderProfile();};
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(themePreference==='system')applyTheme('system');});
applyTheme(themePreference);

document.addEventListener('keydown',e=>{const current=e.target.closest('[role="tab"]');if(!current||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...current.parentElement.querySelectorAll('[role="tab"]')];let i=tabs.indexOf(current);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();const key=tabs[i].dataset.gameSection||tabs[i].dataset.courtSection;tabs[i].click();document.querySelector(`[data-game-section="${key}"], [data-court-section="${key}"]`)?.focus();});

$('#menu-toggle').onclick=()=>{const open=$('#app-menu').hidden;$('#app-menu').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));};
$('#search-toggle').onclick=()=>toggleSearch($('#map-search').hidden);
$('#close-search').onclick=()=>toggleSearch(false);
$('#refit-map').onclick=fitResults;$('#discovery-mode').onchange=e=>{discoveryMode=e.target.value;$('#when-filter').disabled=discoveryMode==='parks';$('#style-filter').disabled=discoveryMode==='parks';renderDiscover();};$('#when-filter').onchange=e=>{whenFilter=e.target.value;renderDiscover();};$('#style-filter').onchange=e=>{styleFilter=e.target.value;renderDiscover();};
document.querySelectorAll('.logo-slot').forEach(el=>el.innerHTML=pinLogo());
document.querySelector('.brand').onclick=e=>{e.preventDefault();go('discover');};

document.addEventListener('keydown',e=>{if(e.key!=='Escape'||$('#detail-dialog').open)return;if(!$('#app-menu').hidden){$('#app-menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').focus();}else if(!$('#map-search').hidden){toggleSearch(false);$('#search-toggle').focus();}else if($('#court-popup')){leafletMap?.closePopup();markerNodes.get(selectedCourt)?.getElement()?.focus();}});
document.addEventListener('click',e=>{if(!$('#app-menu').hidden&&!e.target.closest('#app-menu, #menu-toggle')){$('#app-menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');}});

let directoryController=null,directoryCache=new Map();
async function loadDirectory(place){
 if(!place.trim())return;if(place.trim().toLowerCase()==='phoenix'){await refreshCityDirectory();return;}const local=courts.find(c=>c.name.toLowerCase().includes(place.trim().toLowerCase()));place=local?.city||place;if(place.trim().toLowerCase()==='phoenix'){await refreshCityDirectory();return;}directoryController?.abort();directoryController=new AbortController();const request=directoryController;directoryScope=null;$('#directory-status').textContent='Searching OpenStreetMap parks for tagged basketball courts…';
 try{
 const cached=directoryCache.get(place.toLowerCase()),result=cached||await discoverBasketballParks(place,AbortSignal.any([request.signal,AbortSignal.timeout(45000)]));if(request.signal.aborted)return;directoryCache.set(place.toLowerCase(),result);
 for(const c of result.parks){const existing=courts.find(x=>x.name.toLowerCase()===c.name.toLowerCase()&&Math.abs(x.lat-c.lat)<.02&&Math.abs(x.lng-c.lng)<.02);if(existing){existing.source='OpenStreetMap';existing.sourceUrl=c.sourceUrl;existing.city=result.city;}else if(!courts.some(x=>x.id===c.id||cityNameKey(x.name)===cityNameKey(c.name)))courts.push(c);}
 directoryScope=result.city;try{localStorage.setItem('bucketlist-park-directory',JSON.stringify(courts.filter(c=>(c.source==='OpenStreetMap'||c.hiddenDuplicateOf)&&c.id.startsWith('osm-'))));}catch{}
 $('#directory-status').textContent=result.parks.length+' mapped basketball parks in this search area (about 10 miles). OSM may omit untagged parks; hours/access are not verified.';if(tab==='discover')renderDiscover();
 }catch(error){if(request.signal.aborted)return;$('#directory-status').textContent='Live park lookup unavailable. Showing saved/demo parks; this is not a complete directory. Try again later.';}
}
function enterShowcase(){if(!showcaseMode){personalState=state;save();}showcaseMode=true;state=createShowcase();signedIn=true;try{sessionStorage.setItem('bucketlist-showcase','active');}catch{}save();$('#app-menu').hidden=true;go('stats');toast('Fictional 90-day showcase loaded. Your own data is preserved.');}
function exitShowcase(){showcaseMode=false;state=personalState;signedIn=false;try{sessionStorage.removeItem('bucketlist-showcase');sessionStorage.removeItem('bucketlist-demo-session');}catch{}go('discover');toast('Returned to your preserved personal demo data.');}
function showcaseProgress(){const entries=[...state.stats].sort((a,b)=>a.date.localeCompare(b.date)),first=statSummary(entries.slice(0,8)),recent=statSummary(entries.slice(-8));return `<section class="showcase-progress"><p class="eyebrow">90-DAY FICTIONAL PLAYER JOURNEY</p><h2>${state.stats.length} sessions. Three court communities.</h2><div class="progress-compare"><div><span>FIRST 8 SESSIONS</span><strong>${first.points} PPG</strong></div><div><span>LATEST 8 SESSIONS</span><strong>${recent.points} PPG</strong></div></div>${showcaseChart(entries)}<div class="showcase-links"><button class="secondary" data-go="games">Games & teams</button><button class="secondary" data-go="chats">Group chats</button><button class="secondary" data-go="profile">Player profile</button></div><p class="muted">${state.groups.length} court groups · ${Object.keys(state.teamNames).length} named teams · ${state.stats.reduce((sum,s)=>sum+(s.minutes||0),0)} demo minutes logged</p><p class="note">All people, conversations, attendance, and performance in this showcase are fictional. Your own saved data is kept separate.</p></section>`;}
$('#load-showcase').onclick=enterShowcase;$('#tour-showcase').onclick=enterShowcase;$('#exit-showcase').onclick=exitShowcase;$('#find-live-parks').onclick=()=>loadDirectory($('#location').value.trim()||'Phoenix');
function showCityCoverage(extra=''){const cityCount=courts.filter(c=>c.source==='City of Phoenix'&&!c.hiddenDuplicateOf).length;$('#directory-status').textContent=cityCount+' Phoenix basketball locations from '+phoenixDirectory.courtRecords+' city court records, plus park basketball listings. Saved '+phoenixDirectory.checkedAt.slice(0,10)+'. '+extra;$('#coverage-status').textContent='Phoenix: '+cityCount+' city-listed basketball locations · tap clusters to zoom';}
async function refreshCityDirectory(){showCityCoverage('Refreshing city source…');try{const result=await fetchPhoenixDirectory(fetch,AbortSignal.timeout(20000));mergeCityCourts(result.parks);if(tab==='discover')renderDiscover(false);showCityCoverage('City source refreshed.');}catch{showCityCoverage('Live refresh unavailable; the bundled city directory is still shown.');}}
showCityCoverage();
// The complete retrieved city snapshot is bundled: launch never depends on a live query.


function showcaseChart(entries){if(!entries.length)return '';const max=Math.max(1,...entries.map(e=>e.points)),points=entries.map((e,i)=>`${20+i*280/Math.max(1,entries.length-1)},${105-e.points/max*85}`).join(' ');return `<figure class="progress-chart"><svg viewBox="0 0 320 135" role="img" aria-label="Points per session across ${entries.length} fictional sessions"><path d="M20 10V108H304" stroke="currentColor" fill="none" opacity=".35"/><polyline points="${points}" fill="none" stroke="#f45422" stroke-width="3"/>${entries.map((e,i)=>`<circle cx="${20+i*280/Math.max(1,entries.length-1)}" cy="${105-e.points/max*85}" r="3" fill="#f45422"><title>${esc(e.date)}: ${e.points} points</title></circle>`).join('')}<text x="20" y="128" fill="currentColor" font-size="9">${esc(entries[0].date)}</text><text x="240" y="128" fill="currentColor" font-size="9">${esc(entries.at(-1).date)}</text></svg><figcaption>Points per session · fictional demonstration</figcaption></figure>`;}
function showSessionStats(id){const g=gameById(id),s=state.stats.find(s=>s.gameId===id);if(!g||!s)return;showDialog('COMPLETED SESSION · FICTIONAL',`<p class="eyebrow">${esc(s.date)}</p><h2>${esc(g.title)}</h2><p class="muted">${esc(courtById(g.courtId)?.name)} · ${esc(teamName(id,state.teams[id]||'A'))}</p>${statTiles({count:1,points:s.points,rebounds:s.rebounds,assists:s.assists})}<p class="muted">${s.minutes||0} minutes · ${esc(s.note)}</p><button class="primary full" data-go="stats">View full stats history</button>`);}

function guestProfilePrompt(){return `<section class="guest-profile-prompt"><strong>Meet the crew. Keep your spot.</strong><p>You can browse this game as a guest. A player profile unlocks team participation, player profiles, group chat, and your personal stats history.</p><button type="button" class="primary full" data-create-profile>Create your player profile</button></section>`;}

const publicAppUrl='https://adoblake.github.io/making-bucketlist/';
let installPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
function showShareApp(){showDialog('BRING YOUR CREW',`<h2>Let’s Play.</h2><p class="muted">Open Bucketlist on your phone or scan this code with another phone’s camera.</p><img class="share-qr" src="${window.BUCKETLIST_QR_DATA||new URL('share-qr.png',publicAppUrl).href}" width="210" height="210" alt="QR code opening Bucketlist"><p class="share-link"><a href="${publicAppUrl}" target="_blank" rel="noopener noreferrer">${publicAppUrl}</a></p><div class="card-actions"><button id="native-share" class="primary">Share link</button><button id="copy-share" class="secondary">Copy link</button></div><p class="note">Interactive demo with fictional players and browser-local data. Changes and messages are not shared between phones.</p>`);$('#native-share').onclick=async()=>{try{if(navigator.share)await navigator.share({title:'Bucketlist — Let’s Play.',text:'Find a court, build a team, and explore the demo.',url:publicAppUrl});else await copyAppLink();}catch(e){if(e.name!=='AbortError')toast('Use the link above to share.');}};$('#copy-share').onclick=copyAppLink;}
async function copyAppLink(){try{await navigator.clipboard.writeText(publicAppUrl);toast('App link copied.');}catch{toast('Select and copy the link shown above.');}}
$('#share-app').onclick=showShareApp;
$('#install-app').onclick=async()=>{if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();return;}showDialog('KEEP BUCKETLIST ON YOUR PHONE',`<div class="login-brand">${pinLogo()}<h2>Bucketlist</h2><p>Let’s Play.</p></div><h3>Add to Home Screen</h3><p class="install-steps"><strong>iPhone / iPad:</strong> open the app link in Safari, tap Share, then Add to Home Screen. If offered, enable Open as Web App.<br><br><strong>Android:</strong> open the app link in Chrome, tap the browser menu, then Install app or Add to Home screen.</p><a class="primary full" href="${publicAppUrl}" target="_blank" rel="noopener noreferrer">Open the hosted app</a><p class="note">Use the HTTPS app link for installation. A downloaded HTML file cannot be installed as a web app. Offline mode retains the app shell; live maps and directory lookup require Internet.</p>`);};
